175	export function apiErrorToStatus(code: string): number {
176	  switch (code) {
177	    case 'NOT_FOUND':
178	      return 404;
179	    case 'FORBIDDEN':
180	      return 403;
181	    case 'VALIDATION_ERROR':
182	      return 400;
183	    case 'CONFLICT':
184	      return 409;
185	    default:
186	      return 500;
187	  }
188	}
