190	// ---------------------------------------------------------------------------
191	// Body reading
192	// ---------------------------------------------------------------------------
193	
194	/** Maximum accepted request body size (1 MiB). */
195	export const MAX_BODY_BYTES = 1_048_576;
196	
197	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
198	export class PayloadTooLargeError extends Error {
199	  constructor() {
200	    super('Payload Too Large');
201	    this.name = 'PayloadTooLargeError';
202	  }
203	}
204	
205	/**
206	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
207	 * {@link MAX_BODY_BYTES} (1 MiB).
208	 *
209	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
210	 *   either via Content-Length header pre-check or streaming byte count).
211	 *   **Callers must catch this error and return a 413 response.**
212	 *
213	 * @param req - The incoming HTTP request.
214	 * @returns The full body string.
215	 */
216	function readBody(req: IncomingMessage): Promise<string> {
217	  return new Promise((resolve, reject) => {
218	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
219	    const declaredLength = req.headers['content-length'];
220	    if (declaredLength !== undefined) {
221	      const n = parseInt(declaredLength, 10);
222	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
223	        req.resume();  // drain body data from socket buffer
224	        reject(new PayloadTooLargeError());
225	        return;
226	      }
227	    }
228	
229	    const chunks: Buffer[] = [];
230	    let totalBytes = 0;
231	    let rejected = false;
232	
233	    req.on('data', (chunk: Buffer) => {
234	      if (rejected) return;
235	      totalBytes += chunk.length;
236	      if (totalBytes > MAX_BODY_BYTES) {
237	        rejected = true;
238	        reject(new PayloadTooLargeError());
239	        // Drain remaining data so the 413 response can be sent cleanly.
240	        req.resume();
241	        return;
242	      }
243	      chunks.push(chunk);
244	    });
245	    req.on('end', () => {
246	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
247	    });
248	    req.on('error', (err) => {
249	      if (!rejected) reject(err);
250	    });
251	  });
252	}
253	
254	/**
255	 * Reads and parses the request body as JSON, enforcing the same size limit as
256	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
257	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
258	 *
259	 * @param req - The incoming HTTP request.
260	 * @returns The parsed JSON value.
261	 */
262	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
263	  const raw = await readBody(req);
264	  try {
265	    return JSON.parse(raw);
266	  } catch {
267	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
268	  }
269	}
270	
271	// ---------------------------------------------------------------------------
272	// Router
273	// ---------------------------------------------------------------------------
274	
275	/**
276	 * A declarative body-parsing route entry for {@link buildRoutes} and
277	 * {@link dispatchRoute}.
278	 *
279	 * - `method` — HTTP method (uppercase).
280	 * - `path` — Exact string path or a RegExp with named capture groups.
281	 * - `handler` — Receives the parsed body (or `undefined` when `noBody` is
282	 *   set), any named capture groups extracted from the RegExp match, and the
283	 *   parsed query parameters from the request URL.
284	 * - `statusCode` — Response status code (default `200`). Use `204` for empty
285	 *   responses — the dispatcher writes the header and skips `sendJson()`.
286	 * - `noBody` — When `true`, skip `readJsonBody()`.
287	 */
288	export interface Route {
289	  method: string;
290	  path: string | RegExp;
291	  handler: (body: unknown, groups?: Record<string, string>, query?: URLSearchParams) => Promise<unknown>;
292	  statusCode?: number;
293	  noBody?: boolean;
294	}
295	
296	// ---------------------------------------------------------------------------
297	// Meta helpers
298	// ---------------------------------------------------------------------------
299	
300	/**

301	 * Guards against path-traversal attacks on URL parameters that are used as
302	 * filesystem path segments.
303	 *
304	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
305	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
306	 * callers receive the same status as a missing project — no information leak.
307	 *
308	 * @param segment - The raw URL parameter value to validate.
309	 */
310	function assertSafeSlug(segment: string): void {
311	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
312	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
313	  }
314	}
315	
316	/**
317	 * Reads the `.meta.json` for a namespaced project at
318	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
319	 *
320	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
321	 * when the field is absent or null.
322	 *
323	 * When the meta file exists but contains malformed JSON, the function still
324	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
325	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
326	 * to URL param '…'`) so operators can detect corrupt meta files during
327	 * troubleshooting. API callers always receive the fallback value in this case.
328	 *
329	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
330	 * indicating that the `{repo}/{slug}` combination is not a known project in
331	 * this ledger. This is the project-existence check for namespaced routes.
332	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
333	 * information-hiding: invalid-input and missing-project cases are
334	 * indistinguishable from the client side.
335	 *
336	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
337	 * before any filesystem access is attempted (defence-in-depth).
338	 */
339	export async function resolveRepoName(
340	  ledgerRoot: string,
341	  repoUrlParam: string,
342	  slugUrlParam: string,
343	): Promise<string> {
344	  assertSafeSlug(repoUrlParam);
345	  assertSafeSlug(slugUrlParam);
346	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
347	  let raw: string;
348	  try {
349	    raw = await readFile(metaPath, 'utf-8');
350	  } catch {
351	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
352	  }
353	  try {
354	    const meta = JSON.parse(raw) as { repository_name?: string | null };
355	    return meta.repository_name ?? repoUrlParam;
356	  } catch {
357	    // Malformed .meta.json — project directory exists, fall back to URL param.
358	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
359	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
360	    return repoUrlParam;
361	  }
362	}
363	
364	/**
365	 * Extracts query-string parameters from a full URL string.
366	 * Returns a URLSearchParams instance (empty if no query string present).
367	 *
368	 * Edge-case behaviour:
369	 * - **Bare `?`** (e.g. `/api/foo?`): `url.slice(qIdx + 1)` is `""` → returns
370	 *   an empty `URLSearchParams`. Safe, no exceptions.
371	 * - **Percent-encoded values** (e.g. `?q=hello%20world`): `URLSearchParams`
372	 *   decodes them transparently — `params.get('q')` returns `"hello world"`.
373	 * - **Fragment / hash characters** (e.g. `?x=1#anchor`): the `#` and
374	 *   everything after it are passed through as literal characters inside the
375	 *   query value because no fragment stripping is performed. Browsers strip the
376	 *   fragment before sending the request, so in practice this situation does not
377	 *   arise for server-received URLs.
378	 */
379	function parseQueryString(url: string): URLSearchParams {
380	  const qIdx = url.indexOf('?');
381	  return new URLSearchParams(qIdx !== -1 ? url.slice(qIdx + 1) : '');
382	}
383	
384	// ---------------------------------------------------------------------------
385	// Static file server
386	// ---------------------------------------------------------------------------
387	
388	async function serveStatic(
389	  req: IncomingMessage,
390	  res: ServerResponse,
391	  port: number
392	): Promise<void> {
393	  const urlPath = (req.url ?? '/').split('?')[0]!;
394	  const filePath =
395	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
396	
397	  // Security: prevent path traversal outside PUBLIC_DIR
398	  const resolved = resolve(filePath);
399	  if (!resolved.startsWith(PUBLIC_DIR)) {
400	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
401	    return;
402	  }
403	
404	  const ext = extname(filePath);
405	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
406	
407	  try {
408	    const content = await readFile(filePath);
409	    res.writeHead(200, {
410	      'Content-Type': mimeType,
411	      'Content-Length': content.length,
412	      'Cache-Control': 'no-store',
413	      ...corsHeaders(port),
414	      ...securityHeaders(),
415	    });
416	    res.end(content);
417	  } catch {
418	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
419	  }
420	}
421	
422	// ---------------------------------------------------------------------------
423	// Route dispatcher
424	// ---------------------------------------------------------------------------
425	
426	/**
427	 * Builds the declarative route table consumed by {@link dispatchRoute}.
428	 *
429	 * All closure variables required by route handlers (`ledgerRoot`, `configPath`,
430	 * `orchestratorLogsDir`, `bootVersions`) are captured via arrow functions.
431	 *
432	 * Routes are organized into three sections:
433	 *
434	 *   Section A — Body-parsing routes. These call readJsonBody() internally via
435	 *               the dispatcher. No `noBody` flag — omitting it is the default.
436	 *
437	 *   Section B — Keyword-specific body-free routes. All entries use `noBody: true`.
438	 *               Covers both active namespaced routes (/:repo/:slug/keyword) and
439	 *               deprecated non-namespaced routes (/:slug/keyword). Routes with a
440	 *               fixed keyword suffix are more specific than the Section C catch-alls
441	 *               and MUST be declared before them — see Section B/C ordering note.
442	 *
443	 *   Section C — Catch-all body-free routes. All entries use `noBody: true`.
444	 *               Covers parameterised routes with no fixed suffix keyword, e.g.
445	 *               GET /:repo/:slug (namespaced) and deprecated GET /:slug.
446	 *
447	 * ⚠️  ORDERING CONSTRAINT (load-bearing, not cosmetic):
448	 *     Section B MUST precede Section C. The dispatcher walks the table in
449	 *     declaration order and returns on the first match. A Section C catch-all
450	 *     such as `GET /api/projects/:repo/:slug` would silently shadow all eight
451	 *     deprecated Section B keyword routes (`/:slug/plan`, `/:slug/synthesis`,
452	 *     etc.) if they were declared after it, permanently breaking backward
453	 *     compatibility with pre-namespace clients.
454	 */
455	export function buildRoutes(
456	  ledgerRoot: string,
457	  configPath: string,
458	  orchestratorLogsDir: string,
459	  bootVersions: WorkspaceVersions | null
460	): Route[] {
461	  return [
462	
463	    // =========================================================================
464	    // Section A — Body-parsing routes
465	    // =========================================================================
466	
467	    // PUT /api/config
468	    { method: 'PUT', path: '/api/config',
469	      handler: async (body) => handleUpdateConfig(configPath, body) },
470	    // GET /api/server-info — needs bootVersions closure
471	    { method: 'GET', path: '/api/server-info', noBody: true,
472	      handler: async () => {
473	        const boot = bootVersions ?? captureWorkspaceVersions();
474	        const disk = captureWorkspaceVersions();
475	        const stale =
476	          boot.mcpServer !== disk.mcpServer ||
477	          boot.personas !== disk.personas ||
478	          boot.orchestrator !== disk.orchestrator;
479	        return { stale, bootVersions: boot, diskVersions: disk };
480	      } },
481	    // GET /api/config
482	    { method: 'GET', path: '/api/config', noBody: true,
483	      handler: async () => handleGetConfig(configPath) },
484	    // PATCH /api/projects/:repo/:slug (namespaced)
485	    { method: 'PATCH', path: /^\/api\/projects\/(?<repo>[^/]+)\/(?<slug>[^/]+)$/,
486	      handler: async (body, groups) => {
487	        const repo = decodeURIComponent(groups!.repo!);
488	        const slug = decodeURIComponent(groups!.slug!);
489	        assertSafeSlug(repo);
490	        assertSafeSlug(slug);
491	        const repoName = await resolveRepoName(ledgerRoot, repo, slug);
492	        return handleRenameProject(ledgerRoot, slug, body, repoName);
493	      } },
494	    // @deprecated — Use PATCH /api/projects/:repo/:slug instead.
495	    // PATCH /api/projects/:slug (retained for backward compat)
496	    { method: 'PATCH', path: /^\/api\/projects\/(?<slug>[^/]+)$/,
497	      handler: async (body, groups) =>
498	        handleRenameProject(ledgerRoot, decodeURIComponent(groups!.slug!), body) },
499	    // POST /api/projects/:repo/:slug/reset (namespaced)
500	    { method: 'POST', path: /^\/api\/projects\/(?<repo>[^/]+)\/(?<slug>[^/]+)\/reset$/,

501	      handler: async (body, groups) => {
502	        const repo = decodeURIComponent(groups!.repo!);
503	        const slug = decodeURIComponent(groups!.slug!);
504	        assertSafeSlug(repo);
505	        assertSafeSlug(slug);
506	        const repoName = await resolveRepoName(ledgerRoot, repo, slug);
507	        return handleResetProject(ledgerRoot, slug, body, repoName);
508	      } },
509	    // @deprecated — Use POST /api/projects/:repo/:slug/reset instead.
510	    // POST /api/projects/:slug/reset (retained for backward compat)
511	    { method: 'POST', path: /^\/api\/projects\/(?<slug>[^/]+)\/reset$/,
512	      handler: async (body, groups) =>
513	        handleResetProject(ledgerRoot, decodeURIComponent(groups!.slug!), body) },
514	    // POST /api/orchestrator/start
515	    { method: 'POST', path: '/api/orchestrator/start',
516	      handler: async (body) => handleOrchestratorStart(WORKSPACE_ROOT, body) },
517	    // POST /api/orchestrator/kill/:id
518	    { method: 'POST', path: /^\/api\/orchestrator\/kill\/(?<id>.+)$/, noBody: true,
519	      handler: async (_, groups) =>
520	        handleOrchestratorKill(
521	          decodeURIComponent(groups!.id!), orchestratorLogsDir, ledgerRoot
522	        ) },
523	    // POST /api/orchestrator/dismiss/:id — 204 No Content
524	    { method: 'POST', path: /^\/api\/orchestrator\/dismiss\/(?<id>.+)$/, noBody: true,
525	      statusCode: 204,
526	      handler: async (_, groups) => {
527	        await handleOrchestratorDismiss(
528	          decodeURIComponent(groups!.id!), orchestratorLogsDir, ledgerRoot
529	        );
530	        return undefined;
531	      } },
532	    // POST /api/orchestrator/delete/:id — 204 No Content
533	    { method: 'POST', path: /^\/api\/orchestrator\/delete\/(?<id>.+)$/, noBody: true,
534	      statusCode: 204,
535	      handler: async (_, groups) => {
536	        await handleOrchestratorDelete(
537	          decodeURIComponent(groups!.id!), orchestratorLogsDir
538	        );
539	        return undefined;
540	      } },
541	    // POST /api/repos — 201 Created
542	    { method: 'POST', path: '/api/repos', statusCode: 201,
543	      handler: async (body) => handleCreateRepo(ledgerRoot, body) },
544	    // PUT /api/repos/:repoId
545	    { method: 'PUT', path: /^\/api\/repos\/(?<repoId>[^/]+)$/,
546	      handler: async (body, groups) =>
547	        handleUpdateRepo(ledgerRoot, decodeURIComponent(groups!.repoId!), body) },
548	    // PATCH /api/knowledge/:id
549	    { method: 'PATCH', path: /^\/api\/knowledge\/(?<id>[^/]+)$/,
550	      handler: async (body, groups) =>
551	        handleUpdateKnowledge(ledgerRoot, decodeURIComponent(groups!.id!), body) },
552	    // POST /api/knowledge/:id/move
553	    { method: 'POST', path: /^\/api\/knowledge\/(?<id>[^/]+)\/move$/,
554	      handler: async (body, groups) =>
555	        handleMoveKnowledge(ledgerRoot, decodeURIComponent(groups!.id!), body) },
556	    // PUT /api/models
557	    { method: 'PUT', path: '/api/models',
558	      handler: async (body) => handleSaveModels(body) },
559	    // POST /api/models/load-defaults
560	    { method: 'POST', path: '/api/models/load-defaults', noBody: true,
561	      handler: async () => handleLoadDefaults() },
562	    // PUT /api/model-assignments
563	    { method: 'PUT', path: '/api/model-assignments',
564	      handler: async (body) => handleUpdateAssignments(body) },
565	    // POST /api/model-assignments/replace
566	    { method: 'POST', path: '/api/model-assignments/replace',
567	      handler: async (body) => handleReplaceAssignedModel(body) },
568	    // POST /api/personas/rebuild — conditional ApiError on build failure
569	    { method: 'POST', path: '/api/personas/rebuild', noBody: true,
570	      handler: async () => {
571	        const result = await handleRebuildPersonas(WORKSPACE_ROOT);
572	        if (!result.success) throw new ApiError('BUILD_FAILED', result.output);
573	        return result;
574	      } },
575	
576	    // =========================================================================
577	    // Section B — Keyword-specific body-free routes
578	    //
579	    // ⚠️  These MUST be declared before Section C catch-alls (see ordering note
580	    //     in the JSDoc above). Adding a catch-all before these entries would
581	    //     silently shadow the deprecated keyword routes and break backward compat.
582	    // =========================================================================
583	
584	    // --- Singleton / non-project routes ---
585	
586	    // GET /api/insights
587	    { method: 'GET', path: '/api/insights', noBody: true,
588	      handler: async () => handleGetInsights(ledgerRoot) },
589	
590	    // GET /api/orchestrator/queue
591	    { method: 'GET', path: '/api/orchestrator/queue', noBody: true,
592	      handler: async () => handleGetOrchestratorQueue(orchestratorLogsDir, ledgerRoot) },
593	
594	    // GET /api/orchestrator/run-status/:filename
595	    { method: 'GET', path: /^\/api\/orchestrator\/run-status\/(?<filename>.+)$/, noBody: true,
596	      handler: async (_, groups) =>
597	        handleGetRunStatus(orchestratorLogsDir, decodeURIComponent(groups!.filename!)) },
598	
599	    // GET /api/repos
600	    { method: 'GET', path: '/api/repos', noBody: true,
601	      handler: async (_, _groups, query) =>
602	        handleListRepos(ledgerRoot, query?.get('include_undeclared') === 'true') },
603	
604	    // GET /api/repos/:repoId
605	    { method: 'GET', path: /^\/api\/repos\/(?<repoId>[^/]+)$/, noBody: true,
606	      handler: async (_, groups) =>
607	        handleGetRepo(ledgerRoot, decodeURIComponent(groups!.repoId!)) },
608	
609	    // DELETE /api/repos/:repoId
610	    { method: 'DELETE', path: /^\/api\/repos\/(?<repoId>[^/]+)$/, noBody: true,
611	      handler: async (_, groups) =>
612	        handleDeleteRepo(ledgerRoot, decodeURIComponent(groups!.repoId!)) },
613	
614	    // GET /api/knowledge[?scope&category&tags&repository_name&query&limit&offset]
615	    { method: 'GET', path: '/api/knowledge', noBody: true,
616	      handler: async (_, _groups, query) => {
617	        const params = {
618	          scope: query?.get('scope') ?? undefined,
619	          category: query?.get('category') ?? undefined,
620	          tags: query?.get('tags') ?? undefined,
621	          repository_name: query?.get('repository_name') ?? undefined,
622	          query: query?.get('query') ?? undefined,
623	          limit: query?.get('limit') ?? undefined,
624	          offset: query?.get('offset') ?? undefined,
625	        };
